local Platoboost = {}
Platoboost.__index = Platoboost

-- Tried in this order; the first one that answers is used.
local HOSTS = { "https://api.platoboost.app", "https://api.platoboost.com", "https://api.platoboost.net" }
local LINK_CACHE_TIME = 10 * 60
