    Title = "Items to sell", Desc = "Only selected, sellable items are included.",
    Values = itemOptions, Value = {}, Multi = true,
    Callback = function(selected) selectedSellAllItems = selected or {} end,
})
SellTab:Button({
    Title = "Sell selected", Desc = "Run the original merchant sale flow once for the selected items.", Icon = "package-check",
    Callback = function()
        if SL_POLICY.RollActive then Window:Notify({Title = "Selling", Content = "Stop Stand rolling first.", Type = "Warning"}); return end
        task.spawn(function() Selling.sellAllSelected(table.clone(selectedSellAllItems)) end)
    end,
})
SellTab:Toggle({
    Title = "Repeat selected sales", Desc = "Off by default. Repeats the same selected-item sale action.", Value = false,
    Callback = function(enabled)
        if enabled and SL_POLICY.RollActive then Window:Notify({Title = "Selling", Content = "Stop Stand rolling first.", Type = "Warning"}); return end
        autoSellAllSelectedLoop = enabled == true
        autoSellLoopToken += 1
        local token = autoSellLoopToken
        if enabled then task.spawn(function()
            while autoSellAllSelectedLoop and token == autoSellLoopToken do
                local untilTime = tick() + math.clamp(tonumber(autoSellInterval) or 3, 1, 10) * 60
                while autoSellAllSelectedLoop and token == autoSellLoopToken and tick() < untilTime do task.wait(0.25) end
                if not autoSellAllSelectedLoop or token ~= autoSellLoopToken then break end
                local selected = table.clone(selectedSellAllItems)
                if #selected > 0 then pcall(Selling.sellAllSelected, selected) end
            end
        end) end
    end,
})
SellTab:Slider({
    Title = "Repeat interval", Desc = "Minutes between repeated sales.",
    Value = {Min = 1, Max = 10, Default = 3}, Step = 1,
    Callback = function(value) autoSellInterval = math.clamp(tonumber(value) or 3, 1, 10) end,
})
SellTab:Button({
    Title = "Stop repeating", Desc = "Stops future automatic sale batches.", Icon = "square",
    Callback = function() autoSellAllSelectedLoop = false; autoSellLoopToken += 1 end,
})
SellTab:Paragraph({Title = "No automatic max-stack selling", Desc = "Auto-sell on max and automatic pickup selling are disabled in this build."})


