local InvisibleV2 = {
    Enabled = false,
    Character = nil,
    RootPart = nil,
    RealCFrame = nil,
    AnimationTrack = nil,
    HeartbeatConnection = nil,
    CharacterAddedConnection = nil,
    OriginalTransparency = {},
    OriginalCanCollide = {},
    RenderKey = "MethionInvisibleV2",
}
_G.MethionInvisibleV2Runtime = InvisibleV2

local function loadInvisibleV2Animation(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return nil end
    local animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 2)
    if not animator then return nil end

    local isR15 = humanoid.RigType == Enum.HumanoidRigType.R15
    local animation = Instance.new("Animation")
    animation.AnimationId = isR15 and "rbxassetid://18665825805" or "rbxassetid://215384594"

    local ok, track = pcall(function()
        return animator:LoadAnimation(animation)
    end)
    animation:Destroy()
    if not ok or not track then return nil end

    track.Priority = Enum.AnimationPriority.Action4
    pcall(function() track:Play(0, 0.001, 0) end)
    task.delay(0, function()
        if track then
            pcall(function()
                track.TimePosition = isR15 and 1.95 or 0.4
            end)
        end
    end)
    return track
end

local function stopInvisibleV2()
    InvisibleV2.Enabled = false
    pcall(function()
        RunService:UnbindFromRenderStep(InvisibleV2.RenderKey)
    end)

    if InvisibleV2.HeartbeatConnection then
        pcall(function() InvisibleV2.HeartbeatConnection:Disconnect() end)
        InvisibleV2.HeartbeatConnection = nil
    end

    if InvisibleV2.AnimationTrack then
        pcall(function() InvisibleV2.AnimationTrack:Stop() end)
        pcall(function() InvisibleV2.AnimationTrack:Destroy() end)
        InvisibleV2.AnimationTrack = nil
    end

    local rootPart = InvisibleV2.RootPart
    if rootPart and rootPart.Parent and InvisibleV2.RealCFrame then
        pcall(function()
            rootPart.CFrame = InvisibleV2.RealCFrame
            local velocity = rootPart.AssemblyLinearVelocity
            rootPart.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        end)
    end

    for part, transparency in pairs(InvisibleV2.OriginalTransparency) do
        if part and part.Parent then
            pcall(function() part.Transparency = transparency end)
        end
    end
    for part, canCollide in pairs(InvisibleV2.OriginalCanCollide) do
        if part and part.Parent then
            pcall(function() part.CanCollide = canCollide end)
        end
    end

    table.clear(InvisibleV2.OriginalTransparency)
    table.clear(InvisibleV2.OriginalCanCollide)
    InvisibleV2.Character = nil
    InvisibleV2.RootPart = nil
    InvisibleV2.RealCFrame = nil
end

local function startInvisibleV2()
    local character = LP.Character
    if not character then return false, "Character is not ready yet." end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local rootPart = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not rootPart then
        return false, "Character parts are not ready yet."
    end

    stopInvisibleV2()
    InvisibleV2.Enabled = true
    InvisibleV2.Character = character
    InvisibleV2.RootPart = rootPart

    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            InvisibleV2.OriginalTransparency[part] = part.Transparency
            InvisibleV2.OriginalCanCollide[part] = part.CanCollide
            if part == rootPart then
                part.Transparency = 1
            else
                part.Transparency = 0.5
                part.CanCollide = false
            end
        end
    end

    InvisibleV2.AnimationTrack = loadInvisibleV2Animation(character)
    pcall(function()
        RunService:UnbindFromRenderStep(InvisibleV2.RenderKey)
    end)
    RunService:BindToRenderStep(InvisibleV2.RenderKey, Enum.RenderPriority.Camera.Value - 1, function()
        if InvisibleV2.Enabled and InvisibleV2.Character == character
            and InvisibleV2.RealCFrame and rootPart.Parent then
            pcall(function()
                rootPart.CFrame = InvisibleV2.RealCFrame
                if InvisibleV2.AnimationTrack then
                    InvisibleV2.AnimationTrack:AdjustWeight(0.001)
                end
            end)
        end
    end)

    InvisibleV2.HeartbeatConnection = RunService.Heartbeat:Connect(function()
        if not InvisibleV2.Enabled or InvisibleV2.Character ~= character
            or LP.Character ~= character or not rootPart.Parent then
            return
        end

        local isR15 = humanoid.RigType == Enum.HumanoidRigType.R15
        local dropOffset = humanoid.HipHeight + (rootPart.Size.Y / 2) - 1
        InvisibleV2.RealCFrame = rootPart.CFrame
        rootPart.CFrame = (rootPart.CFrame - Vector3.new(0, dropOffset, 0))
            * CFrame.Angles(math.rad(isR15 and 180 or 90), 0, 0)

        local velocity = rootPart.AssemblyLinearVelocity
        rootPart.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        if InvisibleV2.AnimationTrack then
            pcall(function() InvisibleV2.AnimationTrack:AdjustWeight(100) end)
        end
    end)

    return true
end

function InvisibleV2.Cleanup()
    stopInvisibleV2()
    if InvisibleV2.CharacterAddedConnection then
        pcall(function() InvisibleV2.CharacterAddedConnection:Disconnect() end)
        InvisibleV2.CharacterAddedConnection = nil
    end
end

InvisibleV2.CharacterAddedConnection = LP.CharacterAdded:Connect(function(character)
    if not InvisibleV2.Enabled then return end
    task.delay(0.5, function()
        if InvisibleV2.Enabled and LP.Character == character then
            local ok, reason = startInvisibleV2()
            if not ok then
                stopInvisibleV2()
                miscNotify("Invisible V2", tostring(reason or "Could not re-enable after respawn."), "Warning")
            end
        end
    end)
end)

local InvisibleV2Section = PlayerTab:Section({Title = "Visibility", Side = "right"})
InvisibleV2Section:Toggle({
    Title = "Invisible V2",
    Desc = "NPCs can still see you, but players can't. Equipping your Stand can expose your location.",
    Icon = "eye-off",
    Value = false,
    Callback = function(enabled)
        if enabled then
            local ok, reason = startInvisibleV2()
            if not ok then
