            else
                miscNotify("Invisible V2", "Enabled. NPCs may still detect you, and summoning your Stand may reveal your location.", "Success")
            end
        else
            stopInvisibleV2()
            miscNotify("Invisible V2", "Disabled and character appearance restored.", "Info")
        end
    end,
})

