local function buildPlayerList()
    local list = {"--"}
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP then table.insert(list, plr.Name) end
    end
    table.sort(list, function(a, b)
        if a == "--" then return true end
        if b == "--" then return false end
        return string.lower(a) < string.lower(b)
    end)
    return list
end

local trollSelection = {"--"}
local trollDropdown = nil
local function rebuildTrollDropdown()
    local list = buildPlayerList()
    local valid = {}
    for _, name in ipairs(list) do valid[name] = true end
    local current = {}
    for _, name in ipairs(trollSelection) do
        if valid[name] then table.insert(current, name) end
    end
    if #current == 0 then current = {"--"} end
    trollSelection = current
    local real = {}
    for _, name in ipairs(current) do
        if name ~= "--" then table.insert(real, name) end
    end
    Config.Trolling.TargetPlayers = real

    if trollDropdown then
        pcall(function() trollDropdown:Refresh(list, true) end)
        return
    end
    trollDropdown = TrollTargetsSection:Dropdown({
        Title = "Target Players",
        Desc = "Choose one or more players.",
        Icon = "users",
        Values = list,
        Value = current,
        Multi = true,
        Callback = function(selected)
            if type(selected) ~= "table" then
                selected = selected and {selected} or {}
            end
            trollSelection = selected
            local names = {}
            for _, name in ipairs(selected) do
                if name ~= "--" then table.insert(names, name) end
            end
            Config.Trolling.TargetPlayers = names
        end,
    })
end

