            if playerName ~= "--" then table.insert(names, playerName) end
        end
        trollSelection = names
        Config.Trolling.TargetPlayers = names
        if trollDropdown then pcall(function() trollDropdown:Set(names) end) end
        AirflowCompat:Notify({Title = "Trolling", Content = #names > 0 and ("Selected " .. #names .. " player(s).") or "There are no other players in this server.", Type = #names > 0 and "Success" or "Warning"})
    end,
})
