TrollKidnapSection:Paragraph({
    Title = "Mr. President",
    Desc = "Use Mr. President's kidnap move on your target.",
})
local kidnapTargetName = "--"
local kidnapManualName = ""
local kidnapShuffle = false
local kidnapEnabled = false
local kidnapLoopToken = 0
local kidnapToggle = nil
local kidnapCleanup = nil
local kidnapDropdown = nil
local kidnapBusy = false
local kidnapManualRunning = false
local kidnapLastActionAt = 0

local function kidnapRunActive(token, manualRun)
    return kidnapLoopToken == token
        and (kidnapEnabled == true or (manualRun == true and kidnapManualRunning == true))
end
local function kidnapCooldownActive()
    -- YBA UI builds may place skill cooldown widgets directly under Cooldowns
    -- or under Cooldowns.Frame. Check both layouts like the reference script.
    local playerGui = LP:FindFirstChildOfClass("PlayerGui") or LP:FindFirstChild("PlayerGui")
    local hud = playerGui and playerGui:FindFirstChild("HUD")
    local cooldowns = hud and hud:FindFirstChild("Cooldowns")
    if not cooldowns then return false end

    local function isActive(container, skillName)
        local frame = container and container:FindFirstChild(skillName)
        return frame ~= nil and frame:IsA("Frame") and frame.Visible == true
    end

    local nested = cooldowns:FindFirstChild("Frame")
    return isActive(cooldowns, "Kidnap")
        or isActive(cooldowns, "KIDNAP")
        or isActive(nested, "Kidnap")
        or isActive(nested, "KIDNAP")
end

local function getKidnapTarget()
    local manualQuery = string.lower(tostring(kidnapManualName or "")):match("^%s*(.-)%s*$")
    if manualQuery and manualQuery ~= "" then
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP and string.sub(string.lower(player.Name), 1, #manualQuery) == manualQuery then
                return player
            end
        end
        return nil
    end
    if kidnapShuffle then
        local candidates = {}
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP then table.insert(candidates, player) end
        end
        return #candidates > 0 and candidates[math.random(1, #candidates)] or nil
    end

    -- Some dropdown implementations return the selected option in a one-item table.
    local selectedName = kidnapTargetName
    if type(selectedName) == "table" then selectedName = selectedName[1] end
    if typeof(selectedName) == "Instance" and selectedName:IsA("Player") then
        return selectedName ~= LP and selectedName or nil
    end
    selectedName = tostring(selectedName or "--")
    return selectedName ~= "--" and Players:FindFirstChild(selectedName) or nil
end

-- These helpers must live in the Trolling scope. The similarly named Stand Pilot
-- helpers are declared inside a separate do-block and are not visible here.
local function getKidnapRemoteFunction(character)
    character = character or LP.Character
    if not character then return nil end
    local remoteFunction = character:FindFirstChild("RemoteFunction")
    if not remoteFunction then
        local ok, result = pcall(function()
            return character:WaitForChild("RemoteFunction", 5)
        end)
        if ok then remoteFunction = result end
    end
    return remoteFunction
end

local function getKidnapStandMorph()
    local character = LP.Character
    return character and character:FindFirstChild("StandMorph") or nil
end

local function performKidnap(target, token, manualRun)
    if not target or target == LP then
        return false, "No target selected. Select a player, enter a username, or enable Shuffle Random Target."
    end
    if not target.Parent or not Players:FindFirstChild(target.Name) then
        return false, "The selected target is no longer in this server. Refresh the target list."
    end

    local character = LP.Character
    if not character then return false, "Your character is not loaded yet." end

    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then
        local ok, result = pcall(function()
            return character:WaitForChild("HumanoidRootPart", 5)
        end)
        if ok then root = result end
    end

    local remote = character:FindFirstChild("RemoteEvent")
    if not remote then
        local ok, result = pcall(function()
            return character:WaitForChild("RemoteEvent", 5)
        end)
        if ok then remote = result end
    end
    local remoteFunction = getKidnapRemoteFunction(character)

    if LP.Character ~= character then return false, "Your character respawned; retrying with the new character." end
    if not root or not root:IsA("BasePart") then return false, "HumanoidRootPart is missing from your character." end
    if not remote or not remote:IsA("RemoteEvent") then return false, "Character RemoteEvent did not load." end

    if not getKidnapStandMorph() then
        if remoteFunction and remoteFunction:IsA("RemoteFunction") then
            local summonOk, summonErr = pcall(function()
                remoteFunction:InvokeServer("ToggleStand", "Toggle")
            end)
            if not summonOk then
                return false, "Could not summon Mr. President: " .. tostring(summonErr)
            end
        else
            return false, "Character RemoteFunction is missing; cannot summon Mr. President."
        end

        local deadline = os.clock() + 2
        while os.clock() < deadline
            and kidnapRunActive(token, manualRun)
            and not getKidnapStandMorph() do
            task.wait(0.1)
        end

        if not kidnapRunActive(token, manualRun) then
            return false, "Kidnap attempt was cancelled."
        end
        if not getKidnapStandMorph() then
            return false, "Mr. President did not summon. Check that it is equipped, then toggle the feature again."
        end
    end

    if kidnapCooldownActive() then return false, "Waiting for the Kidnap move cooldown to finish." end

    local targetCharacter = target.Character
    if not targetCharacter then return false, target.Name .. " does not have a character loaded." end
    local targetRoot = targetCharacter:FindFirstChild("HumanoidRootPart")
    if not targetRoot then
        local ok, result = pcall(function()
            return targetCharacter:WaitForChild("HumanoidRootPart", 3)
        end)
        if ok then targetRoot = result end
    end
    if not targetRoot or not targetRoot:IsA("BasePart") then
        return false, "Could not find " .. target.Name .. "'s HumanoidRootPart."
    end

    local originalRootCFrame = root.CFrame
    local originalAnchored = root.Anchored
    local targetHumanoid = targetCharacter:FindFirstChildOfClass("Humanoid")
    local targetCameraSubject = targetHumanoid or targetRoot
    local cameraBeforeKidnap = workspace.CurrentCamera
    local cameraStates = {}
    local KIDNAP_CAMERA_BEFORE = "Methion_Kidnapper_BeforeCamera"
    local KIDNAP_CAMERA_AFTER = "Methion_Kidnapper_AfterCamera"

    local function snapshotKidnapCamera(camera)
        if not camera or cameraStates[camera] then return end
        pcall(function()
            cameraStates[camera] = {
                CameraType = camera.CameraType,
                CameraSubject = camera.CameraSubject,
                CameraCFrame = camera.CFrame,
                CameraFocus = camera.Focus,
            }
        end)
    end
    snapshotKidnapCamera(cameraBeforeKidnap)

    local actionStarted = false
    local kidnapCompleted = false
    local returnedToOriginalPosition = false
    local cleaned = false

    local function focusKidnapCamera()
        local camera = workspace.CurrentCamera
        if not camera then return end
        snapshotKidnapCamera(camera)

        -- Resolve the selected player's current character each frame, so respawns or
        -- a late-loaded Humanoid do not leave the camera following a stale instance.
        local currentTargetCharacter = target.Character
        local latestSubject = currentTargetCharacter
            and (currentTargetCharacter:FindFirstChildOfClass("Humanoid")
                or currentTargetCharacter:FindFirstChild("HumanoidRootPart"))
        if latestSubject and latestSubject.Parent then
            targetCameraSubject = latestSubject
        end
        if targetCameraSubject and targetCameraSubject.Parent then
            pcall(function()
                camera.CameraType = Enum.CameraType.Custom
                camera.CameraSubject = targetCameraSubject
            end)
        end
    end

    local function startKidnapCameraView()
        -- Other features may also set CameraSubject, so maintain this view on both
        -- sides of Roblox's camera update each rendered frame.
        pcall(function() RunService:UnbindFromRenderStep(KIDNAP_CAMERA_BEFORE) end)
        pcall(function() RunService:UnbindFromRenderStep(KIDNAP_CAMERA_AFTER) end)
        RunService:BindToRenderStep(
            KIDNAP_CAMERA_BEFORE,
            Enum.RenderPriority.Camera.Value - 1,
            focusKidnapCamera
        )
        RunService:BindToRenderStep(
            KIDNAP_CAMERA_AFTER,
            Enum.RenderPriority.Last.Value,
            focusKidnapCamera
        )
        focusKidnapCamera()
    end

    local function restoreKidnapCamera()
        pcall(function() RunService:UnbindFromRenderStep(KIDNAP_CAMERA_BEFORE) end)
        pcall(function() RunService:UnbindFromRenderStep(KIDNAP_CAMERA_AFTER) end)

        local currentCamera = workspace.CurrentCamera
        snapshotKidnapCamera(currentCamera)
        local currentCharacter = LP.Character
        local fallbackSubject = currentCharacter and currentCharacter:FindFirstChildOfClass("Humanoid") or nil

        for camera, saved in pairs(cameraStates) do
            if camera then
                pcall(function()
                    camera.CameraType = saved.CameraType or Enum.CameraType.Custom
                    local subject = saved.CameraSubject
                    if not (subject and subject.Parent) then subject = fallbackSubject end
                    if subject and subject.Parent then camera.CameraSubject = subject end
                    if saved.CameraCFrame then camera.CFrame = saved.CameraCFrame end
                    if saved.CameraFocus then camera.Focus = saved.CameraFocus end
                end)
            end
        end
    end

    local function returnCharacterToOriginalPosition()
        if returnedToOriginalPosition then return end
        if root and root.Parent then
            pcall(function()
                root.CFrame = originalRootCFrame
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                root.Anchored = originalAnchored
            end)
        end
        returnedToOriginalPosition = true
    end

    local function cleanup()
        if cleaned then return end
        cleaned = true

        -- If the move was interrupted, recover the character. Once returned, do
        -- not snap them back again after the three-second spectator window.
        if not returnedToOriginalPosition and root and root.Parent then
            pcall(function()
                root.CFrame = originalRootCFrame
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                root.Anchored = originalAnchored
            end)
        elseif root and root.Parent then
            pcall(function() root.Anchored = originalAnchored end)
        end

        restoreKidnapCamera()
        if kidnapCleanup then kidnapCleanup = nil end
    end
    kidnapCleanup = cleanup

    local ok, err = pcall(function()
        -- Start spectating first and let one rendered frame display the chosen
        -- player before moving our character to them.
        startKidnapCameraView()
        RunService.RenderStepped:Wait()
        focusKidnapCamera()
        if not kidnapRunActive(token, manualRun) then return end
        if not targetRoot.Parent then error("Target left or respawned before the grab.") end

        local pos = (targetRoot.CFrame * CFrame.new(0, 0, -1)).Position
        root.CFrame = CFrame.lookAt(pos, targetRoot.Position)
        task.wait(0.05)
        if not kidnapRunActive(token, manualRun) then return end
        if not targetRoot.Parent then error("Target left or respawned before the grab.") end

        root.Anchored = true
        actionStarted = true
        remote:FireServer("InputBegan", { Input = Enum.KeyCode.E })

        local grabStart = os.clock()
        while os.clock() - grabStart < 0.8 do
            if not kidnapRunActive(token, manualRun) then break end
            if targetRoot and targetRoot.Parent then
                pcall(function()
                    local followPos = (targetRoot.CFrame * CFrame.new(0, 0, -1)).Position
                    root.CFrame = CFrame.lookAt(followPos, targetRoot.Position)
                end)
            end
            focusKidnapCamera()
            task.wait()
        end

        pcall(function() remote:FireServer("InputEnded", { Input = Enum.KeyCode.E }) end)
        if not kidnapRunActive(token, manualRun) then return end
        if not targetRoot.Parent then error("Target left or respawned before the Kidnap action.") end

        focusKidnapCamera()
        -- Fire the existing follow-up input at the target, not from underground.
        remote:FireServer("InputBegan", { Input = Enum.KeyCode.Z })
        task.wait(0.08)
        pcall(function() remote:FireServer("InputEnded", { Input = Enum.KeyCode.Z }) end)
        kidnapCompleted = true

        -- Return immediately after triggering the move. The camera is deliberately
        -- left focused on the target for three more seconds after our character returns.
        returnCharacterToOriginalPosition()
        local restoreAt = os.clock() + 3
        while os.clock() < restoreAt do
            if not kidnapRunActive(token, manualRun) then break end
            focusKidnapCamera()
            task.wait(0.05)
        end
    end)

    cleanup()
    if not ok then
        return false, "Kidnap sequence failed: " .. tostring(err)
    end
    if kidnapCompleted and returnedToOriginalPosition then return true end
    if actionStarted then return false, "Kidnap sequence was interrupted before the move completed." end
    return false, "Kidnap sequence did not start; check the target and try again."
end

kidnapDropdown = TrollKidnapSection:Dropdown({
    Title = "Select Player to Kidnap",
    Desc = "Target used by default.",
    Values = buildPlayerList(),
    Value = kidnapTargetName,
    Callback = function(name)
        if type(name) == "table" then name = name[1] end
        if typeof(name) == "Instance" and name:IsA("Player") then name = name.Name end
        kidnapTargetName = tostring(name or "--")
    end,
})
TrollKidnapSection:Button({
    Title = "Refresh Kidnap Targets",
    Desc = "Refresh the list and clear your selection.",
    Icon = "refresh-cw",
    Callback = function()
        pcall(function() kidnapDropdown:Refresh(buildPlayerList(), false) end)
        kidnapTargetName = "--"
        pcall(function() kidnapDropdown:Set("--") end)
        notifyTroll("Mr. President", "Kidnap target list refreshed.", "Success")
    end,
})
TrollKidnapSection:Toggle({
    Title = "Shuffle Random Target",
    Desc = "Pick a random player each time.",
    Icon = "shuffle",
    Value = false,
    Callback = function(state) kidnapShuffle = state == true end,
})
TrollKidnapSection:Input({
    Title = "Manual Target Name",
    Desc = "Enter part of a username. This overrides the other target options.",
    Icon = "search",
    Value = "",
    Placeholder = "Enter username or prefix",
    Callback = function(value) kidnapManualName = tostring(value or "") end,
})
local function hasMrPresidentEquipped()
    local name = string.lower(tostring(currentStandName() or ""))
    name = name:gsub("[^%w]", "")
    return name == "mrpresident"
end

TrollKidnapSection:Button({
    Title = "Manual Kidnap",
    Desc = "Attempt one kidnap immediately using the selected target.",
    Icon = "hand",
    Callback = function()
        if kidnapBusy or kidnapManualRunning then
            notifyTroll("Mr. President", "A kidnap attempt is already running.", "Info")
            return
        end
        if not hasMrPresidentEquipped() then
            notifyTroll("Mr. President", "Equip Mr. President before using Manual Kidnap.", "Warning")
            return
        end
        if kidnapCooldownActive() then
            notifyTroll("Mr. President", "The Kidnap move is still on cooldown.", "Info")
            return
        end

        local target = getKidnapTarget()
        if not target then
            notifyTroll("Mr. President", "Select a player, enter a username, or enable Shuffle Random Target.", "Warning")
            return
        end
        if target == LP then
            notifyTroll("Mr. President", "You cannot kidnap your own player.", "Warning")
            return
        end

        local token = kidnapLoopToken
        if not kidnapEnabled then
            kidnapLoopToken += 1
            token = kidnapLoopToken
        end
        kidnapBusy = true
        kidnapManualRunning = true
        task.spawn(function()
            local callOk, attempted, reason = pcall(function()
                return performKidnap(target, token, true)
            end)
            kidnapBusy = false
            kidnapManualRunning = false

            if not callOk then
                notifyTroll("Mr. President", "Manual kidnap failed: " .. tostring(attempted), "Warning")
            elseif attempted then
                kidnapLastActionAt = tick()
                notifyTroll("Mr. President", "Manual kidnap attempt sent for " .. target.Name .. ".", "Success")
            else
                notifyTroll("Mr. President", tostring(reason or "Manual kidnap did not start."), "Warning")
            end
        end)
    end,
})

kidnapToggle = TrollKidnapSection:Toggle({
    Title = "Enable Mr. President Kidnapper",
    Desc = "Try the move when it is ready, about every 14 seconds.",
    Icon = "package",
    Value = false,
    Callback = function(state)
        if state and not hasMrPresidentEquipped() then
            kidnapEnabled = false
            if kidnapToggle then pcall(function() kidnapToggle:Set(false) end) end
            notifyTroll("Mr. President", "Equip Mr. President before enabling this feature.", "Warning")
            return
        end

        kidnapEnabled = state == true
        kidnapLoopToken += 1
        local token = kidnapLoopToken
        if not kidnapEnabled then
            if kidnapCleanup then pcall(kidnapCleanup) end
            notifyTroll("Mr. President", "Kidnapper disabled.", "Info")
            return
        end

        notifyTroll("Mr. President", "Kidnapper enabled. Choose a target or enable Shuffle Random Target.", "Success")
        task.spawn(function()
            local lastAction = tick() - 14
            local lastNotice = {}
            local function statusNotice(key, message, kind)
                local now = tick()
                if now - (lastNotice[key] or 0) >= 6 then
                    lastNotice[key] = now
                    notifyTroll("Mr. President", message, kind or "Warning")
                end
            end

            while kidnapEnabled and kidnapLoopToken == token do
                task.wait(0.2)
                if not kidnapEnabled or kidnapLoopToken ~= token then break end
                if tick() - math.max(lastAction, kidnapLastActionAt) < 14 then continue end

                if kidnapCooldownActive() then
                    statusNotice("cooldown", "Waiting for the Kidnap move cooldown.", "Info")
                    continue
                end

                local target = getKidnapTarget()
                if not target then
                    statusNotice("target", "No target selected. Select a player, enter a username prefix, or turn on Shuffle Random Target.")
                    continue
                end
                if target == LP then
                    statusNotice("self", "Your own player cannot be the kidnap target.")
                    continue
                end
                if not target.Character then
                    statusNotice("target-character", target.Name .. " has no loaded character yet.", "Info")
                    continue
                end

                if kidnapBusy then continue end
                kidnapBusy = true
                local callOk, attempted, reason = pcall(function()
                    return performKidnap(target, token, false)
                end)
                kidnapBusy = false
                if not callOk then
                    reason = "Kidnap sequence failed: " .. tostring(attempted)
                    attempted = false
                end
                if attempted then
                    lastAction = tick()
                    kidnapLastActionAt = lastAction
                    statusNotice("success", "Kidnap sequence sent for " .. target.Name .. ".", "Success")
                elseif reason and kidnapEnabled and kidnapLoopToken == token then
                    statusNotice("attempt", reason)
                end
            end
        end)
    end,
})

Players.PlayerAdded:Connect(function()
    task.delay(0.5, function()
        rebuildTrollDropdown()
        pcall(function() kidnapDropdown:Refresh(buildPlayerList(), true) end)
    end)
end)
