        if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then controller:Started() end
    end)
    local function readyCharacter()
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        return humanoid and humanoid.Health > 0 and character:FindFirstChild("HumanoidRootPart") and character:FindFirstChild("RemoteFunction")
    end
    local function hasSelectedItems()
        -- Match the collector's real filters without consuming its boosted-target queue.
        for part, data in pairs(Tracked) do
            if part and part:IsDescendantOf(workspace) and Utils.validPos(part) and not Utils.invisible(part)
                and Farm.allowed(data.Name) and not ItemESP.isPlayerOwned(data.Obj, part) then return true end
        end
        return false
    end
    task.spawn(function()
        while alive and SL_POLICY.Alive do
            task.wait(1)
            if not alive then break end
            if not autoEnabled or controller.busy or not Farm.isActive() or competingAutomation() or not readyCharacter() then
                idleSince = nil
            elseif hasSelectedItems() then
                idleSince = nil
            else
                idleSince = idleSince or os.clock()
                if os.clock() - idleSince >= idleDelay then
                    ItemESP.scan()
                    if hasSelectedItems() then idleSince = nil else controller:Start("hop", true) end
                end
            end
        end
    end)
    local api = {}
    function api:RestoreArrival()
        if not arrival then return end
        local data = arrival
        arrival = nil
        idleDelay = math.clamp(tonumber(data.idleDelay) or 15, 5, 60)
        task.spawn(function()
            local deadline = os.clock() + 45
            while alive and not readyCharacter() and os.clock() < deadline do task.wait(0.1) end
            if not alive then return end
            if not readyCharacter() then say("Hub reloaded. Character is not ready; collection stays stopped."); return end
            if data.resumeFarm then setCollector(true, data.candy == true) end
            autoEnabled = data.autoHop == true and canQueue and data.resumeFarm == true
            autoToggle:Set(autoEnabled, true)
            say(data.resumeFarm and "Stand Lab reloaded; item collection resumed." or "Stand Lab reloaded. Ready.")
        end)
    end
    function api:Stop()
        if not alive then return end
        alive, autoEnabled = false, false
        controller:Stop()
        failed:Disconnect()
        started:Disconnect()
    end
    _G.__StandLabSourceV10.GetServerState = function()
        local current = controller.current
        return {busy = controller.busy, autoHop = autoEnabled, reloadEnabled = reloadEnabled,
            queueSupported = canQueue, queued = queued, idleDelay = idleDelay, lastStatus = lastStatus,
            target = current and current.target, action = current and current.kind,
            attempt = current and current.index, recentActivity = table.clone(history)}
    end
    Window.Raw.Gui.Destroying:Connect(function() api:Stop() end)
    return api
end)()


local function createRollDiagnostics(header, window, gui)
local function newRollLogCore(header)
    local log = {Header = header, Entries = {}, States = {}, Dropped = 0, Serial = 0, Started = os.clock(), Alive = true,
        OnChange = nil :: (() -> ())?, Provider = nil :: (() -> any)?, LastSnapshot = nil :: any}
    local function format(value, depth, seen)
        local kind = type(value)
        if typeof(value) == "Instance" then
            local ok, path = pcall(function() return value:GetFullName() end)
            return ok and path or "<unavailable instance>"
        end
        if kind == "string" then return string.format("%q", value:sub(1, 900)) end
        if kind ~= "table" then return tostring(value) end
        if depth >= 8 then return "{...}" end
        if seen[value] then return "<cycle>" end
        seen[value] = true
        local keys, parts = {}, {}
        for key in pairs(value) do table.insert(keys, key) end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        for i = 1, math.min(#keys, 48) do
            local key = keys[i]
            table.insert(parts, tostring(key) .. "=" .. format(value[key], depth + 1, seen))
        end
        if #keys > 48 then table.insert(parts, "... fields omitted") end
        seen[value] = nil
        return "{" .. table.concat(parts, ", ") .. "}"
    end
    function log.Format(value)
        local ok, text = pcall(format, value, 0, {})
        return ok and text or "<format unavailable>"
    end
    function log.Path(object)
        if not object then return "<nil>" end
        local ok, path = pcall(function() return object:GetFullName() end)
        return ok and path or tostring(object)
    end
    function log.Property(object, property)
        local ok, value = pcall(function() return object[property] end)
        if not ok then return "<unavailable>" end
        return value == nil and "<nil>" or value
    end
    function log.Add(event, fields, level)
        if not log.Alive then return end
        local ok = pcall(function()
            log.Serial += 1
            local line = string.format("%04d +%.3fs [%s] %s", log.Serial, os.clock() - log.Started, level or "INFO", event)
            if fields then line ..= " " .. log.Format(fields):sub(1, 1800) end
            table.insert(log.Entries, line)
            if #log.Entries > 240 then table.remove(log.Entries, 1); log.Dropped += 1 end
            if log.OnChange then pcall(log.OnChange) end
        end)
        if not ok then log.Dropped += 1 end
    end
    function log.State(key, reason, fields)
        local previous = log.States[key]
        log.States[key] = {reason = reason, fields = fields}
        if not previous or previous.reason ~= reason then log.Add(key, {reason = reason, details = fields}) end
    end
    function log.Start(event, fields)
        local token = {event = event, at = os.clock()}
        log.Add(event .. ".begin", fields)
        return token
    end
    function log.Finish(token, outcome, fields)
        log.Add(token.event .. "." .. outcome, {duration = os.clock() - token.at, details = fields}, outcome == "error" and "ERROR" or "INFO")
    end
    function log.Snapshot(reason)
        if log.Provider then
            local ok, snapshot = pcall(log.Provider)
            log.LastSnapshot = ok and snapshot or {snapshotError = tostring(snapshot)}
        end
        log.Add("snapshot", {reason = reason or "manual"})
    end
    function log.BuildReport()
        log.Snapshot("copy-report")
        local events = table.concat(log.Entries, "\n")
        if #events > 40000 then events = "[Earlier event text omitted]\n" .. events:sub(-40000) end
        local snapshotText = log.Format(log.LastSnapshot):sub(1, 22000)
        if type(log.LastSnapshot) == "table" and log.LastSnapshot.candidates then
            local state = {}
            for key, value in pairs(log.LastSnapshot) do if key ~= "candidates" then state[key] = value end end
            snapshotText = log.Format(state):sub(1, 12000) .. "\n\nOBSERVED INPUT CANDIDATES\n"
                .. log.Format(log.LastSnapshot.candidates):sub(1, 16000)
        end
        return "STAND LAB v22 — LOCAL SESSION REPORT\n"
            .. log.Format(log.Header) .. "\nElapsed: " .. string.format("%.3f", os.clock() - log.Started)
            .. "s | discarded events: " .. log.Dropped
            .. "\n\nCURRENT LOCAL SNAPSHOT\n" .. snapshotText
            .. "\n\nLATEST DECISION STATES\n" .. log.Format(log.States):sub(1, 8000)
            .. "\n\nSESSION EVENTS\n" .. events
    end
    function log.Try(event, fn)
        local token = log.Start(event)
        local ok, result = xpcall(fn, function(problem)
            if debug and type(debug.traceback) == "function" then return debug.traceback(tostring(problem), 2) end
            return tostring(problem)
        end)
        log.Finish(token, ok and "return" or "error", {result = result})
        if not ok then log.Snapshot(event .. "-error") end
        return ok, result
    end
    function log.Clear()
        log.Entries, log.States, log.Dropped = {}, {}, 0
        log.Add("log.cleared")
    end
    return log
end

local function attachRollLogUI(log, window, gui)
    local tab = window:Tab({Title = "Logs", Icon = "file-text", Desc = "Local Stand Rolls diagnostics."})
    local actions = tab:Section({Title = "Report", Side = "left"})
    local recent = tab:Section({Title = "Recent events", Side = "right"})
    actions:Paragraph({Title = "Session log", Desc = "Records decisions and input attempts. Reproduce the issue, then copy the report."})
    local preview = recent:Paragraph({Title = "Latest activity", Desc = "Recording this session."})
    local function render()
        if not log.Alive then return end
        local lines = {}
        for i = math.max(1, #log.Entries - 9), #log.Entries do table.insert(lines, log.Entries[i]) end
        preview:SetDesc(table.concat(lines, "\n\n"))
    end
    local queued = false
    log.OnChange = function()
        if queued then return end
        queued = true
        task.delay(0.2, function()
            queued = false
            local page = tab.Raw and tab.Raw._page
            if log.Alive and (not page or page.Visible) then pcall(render) end
        end)
    end
    local function showSelectable(text)
        local old = gui:FindFirstChild("SelectableLogReport")
        if old then old:Destroy() end
        local frame = Instance.new("Frame")
        frame.Name = "SelectableLogReport"
        frame.Size = UDim2.fromScale(0.85, 0.8)
        frame.Position = UDim2.fromScale(0.075, 0.1)
        frame.BackgroundColor3 = Color3.fromRGB(25, 21, 32)
        frame.ZIndex = 1000
        frame.Parent = gui
        local scroll = Instance.new("ScrollingFrame")
        scroll.Size = UDim2.new(1, -24, 1, -62)
        scroll.Position = UDim2.fromOffset(12, 48)
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        scroll.CanvasSize = UDim2.fromOffset(0, 0)
        scroll.ScrollBarThickness = 6
        scroll.BackgroundTransparency = 1
        scroll.ZIndex = 1001
        scroll.Parent = frame
        local box = Instance.new("TextBox")
        box.Size = UDim2.new(1, -12, 0, 0)
        box.AutomaticSize = Enum.AutomaticSize.Y
        box.TextWrapped, box.MultiLine, box.ClearTextOnFocus = true, true, false
        box.TextXAlignment, box.TextYAlignment = Enum.TextXAlignment.Left, Enum.TextYAlignment.Top
        box.TextColor3, box.BackgroundTransparency = Color3.new(1, 1, 1), 1
        box.TextSize, box.ZIndex = 13, 1002
        box.Text = text
        box.Parent = scroll
        local close = Instance.new("TextButton")
        close.Size, close.Position = UDim2.fromOffset(100, 30), UDim2.fromOffset(12, 10)
        close.Text, close.ZIndex = "Close report", 1002
        close.Parent = frame
        close.Activated:Connect(function() frame:Destroy() end)
        box:CaptureFocus()
    end
    actions:Button({Title = "Copy report", Icon = "copy", Callback = function()
        local text = log.BuildReport()
        local copied = false
        if type(setclipboard) == "function" then copied = pcall(setclipboard, text) end
        if copied then
            window:Notify({Title = "Logs", Content = "Report copied. Paste it into the chat.", Type = "Success"})
        else
            showSelectable(text)
        end
    end})
    actions:Button({Title = "Show report", Icon = "file-text", Callback = function() showSelectable(log.BuildReport()) end})
    actions:Button({Title = "Snapshot now", Icon = "camera", Callback = function() log.Snapshot("manual"); render() end})
    actions:Button({Title = "Clear log", Icon = "trash-2", Callback = function() log.Clear(); render() end})
    local page = tab.Raw and tab.Raw._page
    if page then page:GetPropertyChangedSignal("Visible"):Connect(function() if page.Visible then pcall(render) end end) end
    gui.Destroying:Connect(function() log.Add("session.closed"); log.Alive = false end)
    return tab
end

    local log = newRollLogCore(header)
    attachRollLogUI(log, window, gui)
    return log
end

local function setupStandLabRolls()
    local player = LP
    local playerGui = player:WaitForChild("PlayerGui")
    local gui = Window.Raw.Gui
    local alive, busy, loopActive, cancelled = true, false, false, false
    local inFlight = 0
    local metrics = {rolls = 0}
    local CONFIG = {RollItem = "Arrow", TargetStand = "", MaxRolls = 0}
    local _targetLevel = 1
    local SKILLS = {"Worthiness"}
    local tab = Window:Tab({Title = "Stand Rolls", Icon = "sparkles", Desc = "Selected Stand or any skin. No automatic selling or bulk skill allocation."})
    local controls = tab:Section({Title = "Roll controls", Side = "left"})
    local display = tab:Section({Title = "Stand showcase", Side = "right"})
    local status = controls:Paragraph({Title = "Status", Desc = "Choose an item and optional Stand, then start."})
    local diagnostics = createRollDiagnostics({build = "v22", player = player.Name, placeId = game.PlaceId,
        placeVersion = game.PlaceVersion, protocol = "ReturnStandData / StandData.Skin"}, Window, gui)
    local function say(message)
        if alive then status:SetDesc(tostring(message)); diagnostics.State("status", tostring(message)) end
    end
    local function sourceBusy()
        local env = type(getgenv) == "function" and getgenv() or _G
        local ap = _G.MethionAutoPrestige
        return State.Farm or State.HalloweenCandyFarm or State.Selling or (ap and (ap.Enabled or ap.Busy))
            or env.QuestFarmEnabled or env.NPCFarmEnabled
    end
    local function checkCancelled()
        if not alive or not SL_POLICY.Alive or (loopActive and cancelled) then error("Stopped", 0) end
        if loopActive and sourceBusy() then error("Another automation started. Stand rolling stopped.", 0) end
    end
-- Wake on the relevant game signals. Heartbeat only handles stop/deadline checks.
local function addWakeSignal(list, signal, changed)
    if signal then table.insert(list, {signal = signal, changed = changed}) end
end

local function fastAwait(predicate, signalFactory, timeout, failure)
    checkCancelled()
    local ready = predicate()
    if ready then return ready end
    local trace = diagnostics.Start("wait", {timeout = timeout, failure = failure})
    local pulse = Instance.new("BindableEvent")
    local connections, generation, listening = {}, 0, true
    local deadline = os.clock() + timeout
    local function wake()
        if listening then generation += 1; pulse:Fire() end
    end
    local heartbeat = RunService.Heartbeat:Connect(function()
        if not alive or not SL_POLICY.Alive or (loopActive and (cancelled or sourceBusy())) or os.clock() >= deadline then wake() end
    end)
    local function disconnectSignals()
        for _, connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections)
    end
    local ok, result = pcall(function()
        while true do
            disconnectSignals()
            for _, specification in ipairs(signalFactory()) do
                local spec = specification
                table.insert(connections, spec.signal:Connect(function(...)
                    if spec.changed and spec.changed(...) == false then return end
                    wake()
                end))
            end
            checkCancelled()
            local before = generation
            local value = predicate()
            if value then return value end
            if os.clock() >= deadline then error(failure, 0) end
            -- A callback may yield while processing input. Do not lose events received then.
            if before == generation then pulse.Event:Wait() end
        end
    end)
    listening = false
    heartbeat:Disconnect()
    disconnectSignals()
    pulse:Destroy()
    diagnostics.Finish(trace, ok and "ready" or "error", {result = result})
    if not ok then error(tostring(result), 0) end
    return result
end

local function characterWakeSignals()
    local signals = {}
    addWakeSignal(signals, player.CharacterAdded)
    addWakeSignal(signals, player:GetPropertyChangedSignal("Character"))
    local character = player.Character
    if character then
        addWakeSignal(signals, character.ChildAdded)
        addWakeSignal(signals, character.AncestryChanged)
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then addWakeSignal(signals, humanoid:GetPropertyChangedSignal("Health")) end
    end
    return signals
end

local function invoke(remote, ...)
    checkCancelled()
    local args, done, ok, result = table.pack(...), false, false, nil
    local payload = type(args[2]) == "table" and args[2] or {}
    local trace = diagnostics.Start("server.request", {remote = diagnostics.Path(remote), command = args[1],
        dataType = payload.DataType, skill = payload.Skill, skillTree = payload.SkillTreeType})
    local finished, waiting = Instance.new("BindableEvent"), true
    inFlight += 1
    task.spawn(function()
        ok, result = pcall(function() return remote:InvokeServer(table.unpack(args, 1, args.n)) end)
        inFlight -= 1
        local data = type(result) == "table" and result.StandData or nil
        diagnostics.Finish(trace, ok and "return" or "error", {resultType = type(result),
            error = not ok and tostring(result) or nil, stand = type(data) == "table" and data.Stand or nil,
            skin = type(data) == "table" and data.Skin or nil, createdDate = type(data) == "table" and data.CreatedDate or nil,
            originalOwner = type(data) == "table" and data.OriginalOwner or nil})
        done = true
        if waiting then finished:Fire() end
    end)
    local accepted, problem = pcall(fastAwait, function() return done end, function()
        return {{signal = finished.Event}}
    end, 10, "Server call timed out. Waiting for it to finish before another run.")
    waiting = false
    finished:Destroy()
    if not accepted then diagnostics.Add("server.wait.error", {error = tostring(problem), inFlight = inFlight}, "ERROR"); error(tostring(problem), 0) end
    checkCancelled()
    if not ok then error(tostring(result), 0) end
    return result
end


local function characterReady()
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then error("Wait for your character to respawn", 0) end
    return character, humanoid
end

local function learnWorthiness(level)
    local character = characterReady()
    local tree = player:FindFirstChild("CharacterSkillTree")
    if not tree then error("CharacterSkillTree isn't available", 0) end
    for i = 1, level do
        checkCancelled()
        if not alive then return false end
        local name = SKILLS[i]
        local value = tree:FindFirstChild(name)
        if not value or not value:IsA("BoolValue") then
            error("Missing skill value: " .. name, 0)
        end
        if not value.Value then
            if player.Character ~= character then error("Character changed; try again", 0) end
            local remote = character:FindFirstChild("RemoteFunction")
            if not remote or not remote:IsA("RemoteFunction") then
                error("Character.RemoteFunction isn't available", 0)
            end
            say("Learning " .. name .. "...")
            invoke(remote, "LearnSkill", {
                Skill = name,
                SkillTreeType = "Character",
            })
            fastAwait(function()
                if player.Character ~= character then error("Character changed; try again", 0) end
                return value.Value
            end, function()
                local signals = characterWakeSignals()
                addWakeSignal(signals, value:GetPropertyChangedSignal("Value"))
                addWakeSignal(signals, value.AncestryChanged)
                return signals
            end, 4, "Worthiness was not confirmed by the game.")
            if not alive then return false end
            if not value.Value then
                error(name .. " wasn't confirmed. Check skill points and prerequisites.", 0)
            end
        end
    end
    return true
end

