local function normalizeName(name)
    return tostring(name):lower():gsub("[^%w]", "")
end
local function standKey(name)
    local key = normalizeName(name)
    if key == "dirtydeedsdonedirtcheap" then return "d4c" end
    if key == "dirtydeedsdonedirtcheaplovetrain" then return "d4clovetrain" end
    if key == "sexpistols" then return "sixpistols" end
    return key
end
local function isTarget(name: string?, target: string): boolean
    return name ~= nil and target ~= "" and standKey(name) == standKey(target)
end
local function validateTarget(kind, target)
    if kind ~= "Arrow" and kind ~= "Rib" then error("Unknown roll item; stopped", 0) end
    if target == "" then return end
    for _, entry in ipairs(STAND_CATALOG) do
        if standKey(target) == standKey(entry.name) and entry.pool == kind then return end
    end
    error("Selected Stand cannot be rolled with this item; stopped", 0)
end

local function toolContainers(character)
    local list, seen = {}, {}
    local function add(container)
        if container and not seen[container] then seen[container] = true; table.insert(list, container) end
    end
    add(character)
    add(player.Character)
    -- This class-first fallback is used elsewhere in the recovered hub source.
    add(player:FindFirstChildOfClass("Backpack"))
    add(player:FindFirstChild("Backpack"))
    for _, child in ipairs(player:GetChildren()) do if child:IsA("Backpack") then add(child) end end
    return list
end

local function findTool(names, character)
    local wanted = {}
    for rank, name in ipairs(names) do wanted[normalizeName(name)] = rank end
    local found, bestRank = nil, math.huge
    for _, container in ipairs(toolContainers(character)) do
        for _, item in ipairs(container:GetDescendants()) do
            if item:IsA("Tool") then
                local rank = wanted[normalizeName(item.Name)]
                if rank and rank < bestRank then
                    found, bestRank = item, rank
                    if rank == 1 then diagnostics.State("inventory.lookup", "found", {wanted = names, name = item.Name, path = diagnostics.Path(item)}); return item end
                end
            end
        end
    end
    diagnostics.State("inventory.lookup", found and "found" or "missing", {wanted = names, name = found and found.Name, path = diagnostics.Path(found)})
    return found
end

local function inventoryWakeSignals()
    local signals = characterWakeSignals()
    addWakeSignal(signals, player.ChildAdded)
    addWakeSignal(signals, player.ChildRemoved)
    for _, container in ipairs(toolContainers(player.Character)) do
        addWakeSignal(signals, container.DescendantAdded)
        addWakeSignal(signals, container.DescendantRemoving)
        addWakeSignal(signals, container.AncestryChanged)
    end
    return signals
end

local function waitForTool(names)
    local trace = diagnostics.Start("inventory.wait", {wanted = names})
    local ok, tool = pcall(fastAwait, function() return findTool(names, player.Character) end,
        inventoryWakeSignals, 8, "Matching item was not available in the live inventory.")
    diagnostics.Finish(trace, ok and "found" or "error", {path = ok and diagnostics.Path(tool) or nil, error = not ok and tostring(tool) or nil})
    checkCancelled()
    if ok then return tool end
    if tostring(tool) ~= "Matching item was not available in the live inventory." then error(tostring(tool), 0) end
    return nil
end

local function useItem(names, isArrow)
    checkCancelled()
    local character, humanoid = characterReady()
    local tool = waitForTool(names)
    if not tool then error("Couldn't find the requested item in your current inventory.", 0) end
    if isArrow and not learnWorthiness(1) then return end
    checkCancelled()
    if player.Character ~= character then error("Character changed; try again", 0) end
    diagnostics.Add("item.equip", {name = tool.Name, path = diagnostics.Path(tool), enabled = diagnostics.Property(tool, "Enabled")})
    humanoid:EquipTool(tool)
    fastAwait(function()
        if player.Character ~= character then error("Character changed while equipping", 0) end
        return tool.Parent == character and tool.Enabled ~= false
    end, function()
        local signals = characterWakeSignals()
        addWakeSignal(signals, tool.AncestryChanged)
        addWakeSignal(signals, tool:GetPropertyChangedSignal("Enabled"))
        return signals
    end, 5, "Item did not become ready to activate.")
    checkCancelled()
    -- Equipping can yield; read Worthiness again immediately before activation.
    if isArrow and not learnWorthiness(1) then return end
    checkCancelled()
    diagnostics.Add("item.activate.begin", {name = tool.Name, parent = diagnostics.Path(tool.Parent)})
    tool:Activate()
    diagnostics.Add("item.activate.return", {name = tool.Name, enabled = diagnostics.Property(tool, "Enabled")})
    say("Using " .. tool.Name .. "...")
    return tool.Name, tool
end


local function visible(object)
    local current = object
    while current and current ~= playerGui do
        if current:IsA("GuiObject") and not current.Visible then return false end
        if current:IsA("ScreenGui") and not current.Enabled then return false end
        current = current.Parent
    end
    return current == playerGui
end

local function _confirmYes()
    local matches = {}
    for _, object in ipairs(playerGui:GetDescendants()) do
        if object:IsA("TextButton") and not object:IsDescendantOf(gui)
            and visible(object) and object.Text:match("^%s*[Yy][Ee][Ss]%s*$") then
            table.insert(matches, object)
        end
    end
    if #matches ~= 1 then
        error("Found " .. #matches .. " visible Yes buttons. Finish dialogue or click manually.", 0)
    end
    if type(firesignal) ~= "function" then
        error("Your runner lacks firesignal; click the game's Yes button manually.", 0)
    end
    firesignal(matches[1].MouseButton1Click)
    say("Sent Yes click. Waiting for the game result.")
end


local ARROWS = {"Mysterious Arrow", "Redeemed Mysterious Arrow"}
local RIBS = {"Rib Cage of The Saint's Corpse", "Redeemed Rib Cage of The Saint's Corpse"}
local function rollItems()
    return CONFIG.RollItem == "Rib" and RIBS or ARROWS
end
local FRUIT = {"Rokakaka", "Redeemed Rokakaka"}

local function standName(): string?
    local stats = player:FindFirstChild("PlayerStats")
    local stand = stats and stats:FindFirstChild("Stand")
    if not stand or not stand:IsA("StringValue") then
        error("Cannot read PlayerStats.Stand; stopped", 0)
    end
    local value = stand.Value
    if value == "None" or value == "" then return nil end
    return value
end

local function waitReady(timeout)
    return fastAwait(function()
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health > 0 and character:FindFirstChild("RemoteFunction") then return character end
        return nil
    end, characterWakeSignals, timeout, "Character did not become ready; stopped.")
end

-- Visible choices can appear before ClientFunctions attaches their click handler.
local pendingInputHandler = nil

local function pendingHandlerReady()
    local button = pendingInputHandler
    if not button or not button.Parent or not visible(button) or type(getconnections) ~= "function" then return true end
    local ok, connections = pcall(function() return getconnections(button.MouseButton1Click) end)
    if not ok or type(connections) ~= "table" then return true end
    for _, connection in pairs(connections) do
        local enabledOk, enabled = pcall(function() return connection.Enabled end)
        local connectedOk, connected = pcall(function() return connection.Connected end)
        if (not enabledOk or enabled ~= false) and (not connectedOk or connected ~= false) then return true end
    end
    return false
end

local function inputSignalDetails(button)
    local result = {}
    for _, name in ipairs({"MouseButton1Click", "Activated", "MouseButton1Down"}) do
        local entry = {api = type(getconnections), handlers = {}}
        local ok, signal = pcall(function() return button[name] end)
        if ok and type(getconnections) == "function" then
            local got, connections = pcall(getconnections, signal)
            entry.ok, entry.resultType = got, type(connections)
            if got and type(connections) == "table" then
                entry.count = 0
                for _ in pairs(connections) do entry.count += 1 end
                local included = 0
                for key, connection in pairs(connections) do
                    included += 1
                    if included > 12 then break end
                    local callback = diagnostics.Property(connection, "Function")
                    local handler = {key = tostring(key), fire = type(diagnostics.Property(connection, "Fire")),
                        enabled = diagnostics.Property(connection, "Enabled"), connected = diagnostics.Property(connection, "Connected"),
                        callbackType = type(callback)}
                    if type(callback) == "function" and type(getfenv) == "function" then
                        local environmentOk, environment = pcall(getfenv, callback)
                        if environmentOk and type(environment) == "table" then handler.script = diagnostics.Path(environment.script) end
                    end
                    table.insert(entry.handlers, handler)
                end
            elseif not got then entry.error = tostring(connections) end
        else entry.signalAvailable = ok end
        result[name] = entry
    end
    return result
end

local function clickSignal(button)
    checkCancelled()
    if not button or not button:IsA("GuiButton") then
        pendingInputHandler = nil
        diagnostics.Add("input.dispatch.invalid", {button = diagnostics.Path(button)}, "WARN")
        return false, "invalid-input"
    end
    local connections = nil
    if type(getconnections) == "function" then
        local ok, found = pcall(function() return getconnections(button.MouseButton1Click) end)
        if ok and type(found) == "table" then
            connections = {}
            local total = 0
            for index, connection in pairs(found) do
                total += 1
                local enabledOk, enabled = pcall(function() return connection.Enabled end)
                local connectedOk, connected = pcall(function() return connection.Connected end)
                if (not enabledOk or enabled ~= false) and (not connectedOk or connected ~= false) then
                    table.insert(connections, {index = index, connection = connection})
                end
            end
            if #connections == 0 then
                pendingInputHandler = button
                diagnostics.State("input.readiness", "waiting-for-handler", {button = diagnostics.Path(button),
                    event = "MouseButton1Click", total = total, active = 0})
                -- A successful firesignal call with no listener was the observed v18 failure.
                return false, "handlers-not-ready"
            end
            diagnostics.State("input.readiness", "ready", {button = diagnostics.Path(button), total = total, active = #connections})
        else
            diagnostics.State("input.readiness", "inspection-unavailable", {button = diagnostics.Path(button),
                resultType = type(found), error = not ok and tostring(found) or nil})
        end
    end
    pendingInputHandler = nil
    diagnostics.Add("input.dispatch.begin", {button = diagnostics.Path(button), class = button.ClassName,
        text = diagnostics.Property(button, "Text"), signal = "MouseButton1Click"})
    if connections then
        local fired = false
        for _, entry in ipairs(connections) do
            checkCancelled()
            local connection = entry.connection
            local success, returned = pcall(function() return connection:Fire() end)
            diagnostics.Add("input.handler.return", {index = entry.index, ok = success, returned = diagnostics.Format(returned),
                enabled = diagnostics.Property(connection, "Enabled")}, success and "INFO" or "ERROR")
            if success then fired = true end
        end
        if fired then return true, "handler-dispatched" end
    end
    if type(firesignal) == "function" then
        local ok, returned = pcall(function() return firesignal(button.MouseButton1Click) end)
        diagnostics.Add("input.firesignal.return", {ok = ok, returned = diagnostics.Format(returned)}, ok and "INFO" or "ERROR")
        return ok, ok and "signal-dispatched" or "signal-error"
    end
    diagnostics.Add("input.dispatch.unavailable", {getconnections = type(getconnections), firesignal = type(firesignal)}, "WARN")
    return false, "dispatch-unavailable"
end


local function textOf(object)
    if object:IsA("TextButton") or object:IsA("TextLabel") or object:IsA("TextBox") then
        return object.Text:gsub("<[^>]*>", ""):lower()
    end
    return ""
end

-- Protocol observed from the user's real View Stand Data click:
-- Character.RemoteFunction:InvokeServer("ReturnStandData", {DataType="Stand", ReturnStandModel=cache})
-- Response: {StandData={Stand, Skin, CreatedDate, OriginalOwner}, StandModel=Model}
local skinProof = nil
local skinLine = nil
local standModelCache = {}
local latestStandSnapshot = nil
local ownedStandPreview = nil
local previewCacheFolder = nil

local function setSkinLine(value)
    if skinLine and alive then
        skinLine:SetDesc("Skin: " .. (value == nil and "Unknown" or value == "" and "None" or value))
    end
end

local function releaseReturnedModel(model)
    if typeof(model) ~= "Instance" or not model:IsA("Model") or model == ownedStandPreview then return end
    local character = player.Character
    if character and model:IsDescendantOf(character) then return end
    if model.Parent ~= player then return end
    -- This exact zero-argument cleanup event was observed after the real query.
    local clean = model:FindFirstChild("CleanRemoteEvent")
    if clean and clean:IsA("RemoteEvent") then pcall(function() clean:FireServer() end) end
end

local function keepStandPreview(model, data)
    if model == ownedStandPreview and ownedStandPreview and ownedStandPreview.Parent then return ownedStandPreview end
    local copy = nil
    if typeof(model) == "Instance" and model:IsA("Model") and model:FindFirstChildWhichIsA("BasePart", true) then
        pcall(function() copy = model:Clone() end)
    end
    if copy then
        -- Store only local geometry. Executable children and remotes are not needed by the viewer.
        for _, child in ipairs(copy:GetDescendants()) do
            if child:IsA("LuaSourceContainer") or child:IsA("RemoteEvent") or child:IsA("RemoteFunction") then
                child:Destroy()
            elseif child:IsA("BasePart") then
                child.CanCollide, child.CanTouch, child.CanQuery = false, false, false
                child.Anchored = true
            end
        end
        if not previewCacheFolder or not previewCacheFolder.Parent then
            previewCacheFolder = Instance.new("Folder")
            previewCacheFolder.Name = "StandDataPreviewCache"
            previewCacheFolder.Parent = gui
        end
        copy.Parent = previewCacheFolder
    end
    if ownedStandPreview then pcall(function() ownedStandPreview:Destroy() end) end
    ownedStandPreview = copy
    standModelCache = {}
    if copy then
        -- Observed key structure: Stand name followed by the raw Skin string.
        standModelCache[data.Stand .. data.Skin] = {StandMorph = copy}
    end
    releaseReturnedModel(model)
    return copy
end

local function fetchStandSnapshot()
    checkCancelled()
    latestStandSnapshot = nil
    local expected = standName()
    if not expected then error("No Stand available to inspect", 0) end
    local character = waitReady(20)
    local remote = character:FindFirstChild("RemoteFunction")
    if not remote or not remote:IsA("RemoteFunction") then error("Stand data is unavailable. Current Stand kept.", 0) end
    local response = invoke(remote, "ReturnStandData", {
        DataType = "Stand",
        ReturnStandModel = standModelCache,
    })
    checkCancelled()
    if player.Character ~= character or standName() ~= expected then
        if type(response) == "table" then releaseReturnedModel(response.StandModel) end
        error("Stand changed during inspection. Current Stand kept.", 0)
    end
    local data = type(response) == "table" and response.StandData or nil
    if type(data) ~= "table" or type(data.Stand) ~= "string" or type(data.Skin) ~= "string"
        or data.Skin:match("^%s*$") or type(data.CreatedDate) ~= "number" or type(data.OriginalOwner) ~= "number" then
        if type(response) == "table" then releaseReturnedModel(response.StandModel) end
        error("Stand data response could not be verified. Current Stand kept.", 0)
    end
    if normalizeName(data.Stand) ~= normalizeName(expected) then
        releaseReturnedModel(response.StandModel)
        error("Server returned a different Stand. Current Stand kept.", 0)
    end
    local skin = data.Skin == "None" and "" or data.Skin
    local snapshot = {
        character = character, stand = expected, skin = skin, rawSkin = data.Skin,
        createdDate = data.CreatedDate, originalOwner = data.OriginalOwner, checkedAt = os.clock(),
    }
    -- Preview failure must not change the authoritative StandData result.
    local previewOk, preview = pcall(keepStandPreview, response.StandModel, data)
    if previewOk then snapshot.model = preview else releaseReturnedModel(response.StandModel) end
    latestStandSnapshot = snapshot
    return snapshot
end

local function checkedSkinIsBlank(expectedStand): boolean
    local proof = skinProof
    skinProof = nil
    if not proof or proof.character ~= player.Character or proof.stand ~= expectedStand
        or standName() ~= expectedStand or os.clock() - proof.checkedAt > 20 then setSkinLine(nil); return false end
    -- Requery immediately before fruit and again before confirming its dialogue.
    local ok, fresh = pcall(fetchStandSnapshot)
    checkCancelled()
    if not ok then setSkinLine(nil); return false end
    setSkinLine(fresh.skin)
    if fresh.skin ~= "" or fresh.stand ~= proof.stand or fresh.createdDate ~= proof.createdDate
        or fresh.originalOwner ~= proof.originalOwner then return false end
    skinProof = fresh
    return true
end

local function readSkin(): (string, string)
    skinProof = nil
    setSkinLine(nil)
    local snapshot = fetchStandSnapshot()
    if snapshot.skin == "" then skinProof = snapshot end
    setSkinLine(snapshot.skin)
    return snapshot.skin, snapshot.stand
end

_G.__StandLabSourceV10.GetCurrentStandPreview = function()
    local snapshot = latestStandSnapshot
    if not alive or not snapshot or snapshot.character ~= player.Character or snapshot.stand ~= standName()
        or not snapshot.model or not snapshot.model.Parent then return nil end
    return snapshot.model, snapshot.skin
end

-- Caption rules retain the existing Yes path and add the user's observed Rib Cage acceptance.
local function choiceCaption(button): string
    local parts = {}
    if button:IsA("TextButton") and textOf(button):match("%S") then return textOf(button) end
    local seen = {}
    for _, child in ipairs(button:GetDescendants()) do
        if child:IsA("TextLabel") then
            local text = textOf(child)
            if not seen[text] then seen[text] = true; table.insert(parts, text) end
        end
    end
    return table.concat(parts, " "):match("^%s*(.-)%s*$") or ""
end

local function dialogueWakeSignals(revisions)
    local signals = characterWakeSignals()
    -- Subscribe even before a candidate exists: the next predicate can discover it.
    -- Only inspect a pending handler; do not rescan the GUI on idle frames.
    addWakeSignal(signals, RunService.Heartbeat, function()
        if not pendingInputHandler then return false end
        if not pendingInputHandler.Parent or not visible(pendingInputHandler) then
            pendingInputHandler = nil
            return true
        end
        return pendingHandlerReady()
    end)
    addWakeSignal(signals, playerGui.ChildAdded)
    addWakeSignal(signals, playerGui.ChildRemoved)
    local stats = player:FindFirstChild("PlayerStats")
    local stand = stats and stats:FindFirstChild("Stand")
    if stand then addWakeSignal(signals, stand:GetPropertyChangedSignal("Value")) end
    local dialogue = playerGui:FindFirstChild("DialogueGui")
    if dialogue then
        addWakeSignal(signals, dialogue.DescendantAdded)
        addWakeSignal(signals, dialogue.DescendantRemoving)
        addWakeSignal(signals, dialogue.AncestryChanged)
        local objects = {dialogue}
        for _, object in ipairs(dialogue:GetDescendants()) do table.insert(objects, object) end
        for _, object in ipairs(objects) do
            local observed = object
            local function visibilityChanged()
                if revisions then revisions[observed] = (revisions[observed] or 0) + 1 end
            end
            if object:IsA("GuiObject") then addWakeSignal(signals, object:GetPropertyChangedSignal("Visible"), visibilityChanged) end
            if object:IsA("ScreenGui") then addWakeSignal(signals, object:GetPropertyChangedSignal("Enabled"), visibilityChanged) end
            if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                addWakeSignal(signals, object:GetPropertyChangedSignal("Text"))
            end
            if object:IsA("GuiButton") then
                local ok, signal = pcall(function() return object:GetPropertyChangedSignal("Interactable") end)
                if ok then addWakeSignal(signals, signal, visibilityChanged) end
            end
        end
    end
    return signals
end

local function chooseItemAction(itemName, revisions)
    local dialogue = playerGui:FindFirstChild("DialogueGui")
    if not dialogue then diagnostics.State("dialogue.match", "missing-root", {expected = "PlayerGui.DialogueGui", item = itemName}); return nil end
    local base = normalizeName((itemName:gsub("^Redeemed ", "")))
    local parts = {}
    for _, object in ipairs(dialogue:GetDescendants()) do
        if object:IsA("GuiObject") and visible(object) then
            local text = textOf(object)
            if text ~= "" then table.insert(parts, text) end
        end
    end
    local context = normalizeName(table.concat(parts, " "))
    if not context:find(base, 1, true) then
        diagnostics.State("dialogue.match", "context-mismatch", {item = itemName, base = base,
            root = diagnostics.Path(dialogue), visibleTexts = #parts, context = context:sub(1, 700)})
        return nil
    end
    if (base == "mysteriousarrow" or base == "ribcageofthesaintscorpse")
        and (context:find("notworthy", 1, true) or context:find("notnotworthy", 1, true)) then
        diagnostics.Add("dialogue.rejected", {item = itemName, reason = "not-worthy", context = context:sub(1, 700)}, "WARN")
        error("Game rejected this item: Worthiness is not ready. Stopped.", 0)
    end
    local accept, advance, seen = nil, nil, {}
    for _, object in ipairs(dialogue:GetDescendants()) do
        if object:IsA("GuiButton") and visible(object) then
            local button, ancestor = object, object.Parent
            while ancestor and ancestor ~= dialogue do
                if ancestor:IsA("GuiButton") then button = ancestor end
                ancestor = ancestor.Parent
            end
            local enabledOk, interactable = pcall(function() return button.Interactable end)
            if not seen[button] and (not enabledOk or interactable ~= false) then
                seen[button] = true
                local caption = normalizeName(choiceCaption(button))
                local name = button.Name:lower()
                local isAccept = caption == "yes"
                    or (base == "ribcageofthesaintscorpse" and caption == "acceptandletitmergewithyoursoul")
                if isAccept then
                    if accept and accept ~= button then error("Multiple acceptance choices; stopped", 0) end
                    accept = button
                elseif caption ~= "no" and not caption:match("^reject") and (caption == "continue" or caption == "clicktocontinue" or caption == "skip" or caption == "advance"
                    or name:find("continue", 1, true) or name:find("skip", 1, true) or name:find("advance", 1, true)) then
                    advance = advance or button
                end
            end
        end
    end
    local button = accept or advance
    if not button then diagnostics.State("dialogue.match", "no-eligible-input", {item = itemName, root = diagnostics.Path(dialogue), context = context:sub(1, 700)}); return nil end
    local revision, current = 0, button
    while current and current ~= playerGui do revision += revisions[current] or 0; current = current.Parent end
    local kind = accept and "accept" or "advance"
    -- Dispatch once per visible appearance. Typewriter text must not trigger another click.
    local phase = kind .. ":" .. normalizeName(choiceCaption(button)) .. ":" .. revision
    diagnostics.State("dialogue.match", "candidate-ready", {item = itemName, button = diagnostics.Path(button), class = button.ClassName, caption = choiceCaption(button), kind = kind, phase = phase:sub(1, 700)})
    return button, kind, phase
end

local function itemDialogue(itemName, done)
    diagnostics.ActiveItem = itemName
    diagnostics.Add("dialogue.begin", {item = itemName})
    local revisions = setmetatable({}, {__mode = "k"})
    local lastButton, lastPhase = nil, nil
    say("Waiting for " .. itemName .. "...")
    fastAwait(function()
        checkCancelled()
        if done() then pendingInputHandler = nil; diagnostics.State("dialogue.progress", "completed", {item = itemName}); return true end
        local button, kind, phase = chooseItemAction(itemName, revisions)
        if pendingInputHandler and pendingInputHandler ~= button then pendingInputHandler = nil end
        if button and (button ~= lastButton or phase ~= lastPhase) then
            local base = normalizeName((itemName:gsub("^Redeemed ", "")))
            if kind == "accept" and base == "rokakaka" then
                diagnostics.Add("fruit.validation.begin", {stand = standName()})
                if not checkedSkinIsBlank(standName()) or isTarget(standName(), CONFIG.TargetStand) then
                    diagnostics.Add("fruit.validation.blocked", nil, "WARN")
                    error("Skin data changed before fruit confirmation; stopped", 0)
                end
                diagnostics.Add("fruit.validation.accepted")
                -- Revalidation yields for the server. Confirm the input is still the same afterward.
                local current, currentKind, currentPhase = chooseItemAction(itemName, revisions)
                if current ~= button or currentKind ~= kind or currentPhase ~= phase then diagnostics.State("dialogue.progress", "input-changed-during-validation"); return false end
            end
            local returned, dispatchReason = clickSignal(button)
            local progress = returned and "dispatch-returned-awaiting-game" or (dispatchReason == "handlers-not-ready" and "waiting-for-handler" or "dispatch-failed")
            diagnostics.State("dialogue.progress", progress, {button = diagnostics.Path(button), item = itemName, dispatchReason = dispatchReason})
            if returned then lastButton, lastPhase = button, phase end
        elseif button then
            diagnostics.State("dialogue.progress", "unchanged-input-already-dispatched", {button = diagnostics.Path(button), item = itemName})
        end
        return done()
    end, function() return dialogueWakeSignals(revisions) end, 30, itemName .. " dialogue did not complete; stopped.")
end

local function waitItemSettled(tool, expectWorthinessReset, resetCharacter, grantedStand)
    local unequipAttempted = false
    fastAwait(function()
        if grantedStand and standName() ~= grantedStand then
            error("Stand changed while finishing item use; stopped.", 0)
        end
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local reason = nil
        if resetCharacter and character == resetCharacter then
            reason = "waiting-for-replacement-character"
        elseif not character or not character.Parent then
            reason = "character-not-parented"
        elseif not humanoid or humanoid.Health <= 0 then
            reason = "character-not-alive"
        elseif not character:FindFirstChild("HumanoidRootPart") then
            reason = "missing-character-root"
        elseif not character:FindFirstChild("RemoteEvent") or not character:FindFirstChild("RemoteFunction") then
            reason = "missing-character-remotes"
        elseif Gui.currentDialogue() ~= nil then
            reason = "dialogue-still-open"
        elseif tool and tool.Parent == character and not grantedStand then
            reason = "used-tool-still-equipped"
        end
        if expectWorthinessReset then
            local tree = player:FindFirstChild("CharacterSkillTree")
            local worthiness = tree and tree:FindFirstChild("Worthiness")
            if not worthiness or not worthiness:IsA("BoolValue") or worthiness.Value ~= false then
                reason = reason or "waiting-for-worthiness-reset"
            else
                diagnostics.State("reset.readiness", "worthiness-reset-confirmed")
            end
        end
        -- PlayerStats confirmed the result and the dialogue has closed. A Rib Cage can
        -- remain equipped after a successful grant, so its Parent is not completion proof.
        if not reason and grantedStand and tool and tool.Parent == character and not unequipAttempted then
            unequipAttempted = true
            diagnostics.Add("item.release.begin", {tool = diagnostics.Path(tool), grantedStand = grantedStand})
            -- Normal Humanoid unequip; never destroy or reactivate the retained item.
            local ok, problem = pcall(function() humanoid:UnequipTools() end)
            diagnostics.Add("item.release.return", {ok = ok, error = not ok and tostring(problem) or nil,
                toolParent = diagnostics.Path(tool.Parent)}, ok and "INFO" or "WARN")
            checkCancelled()
            if player.Character ~= character then return false end
            if standName() ~= grantedStand then error("Stand changed while finishing item use; stopped.", 0) end
        end
        diagnostics.State("item.settle", reason or "ready", {character = diagnostics.Path(character),
            replacementConfirmed = resetCharacter ~= nil and character ~= resetCharacter,
            tool = diagnostics.Path(tool), toolParent = diagnostics.Path(tool and tool.Parent),
            health = humanoid and humanoid.Health})
        return reason == nil
    end, function()
        local signals = dialogueWakeSignals()
        local character = player.Character
        if character then addWakeSignal(signals, character.ChildRemoved) end
        if tool then addWakeSignal(signals, tool.AncestryChanged) end
        if expectWorthinessReset then
            addWakeSignal(signals, player.ChildAdded)
            addWakeSignal(signals, player.ChildRemoved)
            local tree = player:FindFirstChild("CharacterSkillTree")
            if tree then
                addWakeSignal(signals, tree.ChildAdded)
                addWakeSignal(signals, tree.ChildRemoved)
                addWakeSignal(signals, tree.AncestryChanged)
                local worthiness = tree:FindFirstChild("Worthiness")
                if worthiness then addWakeSignal(signals, worthiness:GetPropertyChangedSignal("Value")) end
            end
        end
        return signals
    end, 35, "Item use is not ready yet; see Logs > item.settle for the blocking state.")
end


local function rollUntilSkin()
    local names = rollItems()
    local target = CONFIG.TargetStand
    validateTarget(CONFIG.RollItem, target)
    local itemLabel = CONFIG.RollItem == "Rib" and "Rib Cages" or "arrows"
    local rolls = 0
    metrics.rolls = 0
    while alive and not cancelled do
        waitReady(25)
        local currentName = standName()
        if isTarget(currentName, target) then
            return "TARGET FOUND: " .. currentName .. ". Kept!"
        end
        if currentName then
            say("Checking skin on " .. currentName .. "...")
            local skin, inspectedName = readSkin()
            if skin ~= "" then
                return "SKIN FOUND: " .. skin .. " (" .. inspectedName .. "). Kept!"
            end
            if CONFIG.MaxRolls > 0 and rolls >= CONFIG.MaxRolls then
                return "Roll limit reached. Final Stand kept."
            end
            -- Do not remove the current Stand if there is no next arrow.
            if not waitForTool(names) then return "No usable " .. itemLabel .. " found in the live inventory. Current Stand kept." end
            if not waitForTool(FRUIT) then return "No usable Rokakaka found in the live inventory. Current Stand kept." end
            checkCancelled()
            if not checkedSkinIsBlank(inspectedName) or isTarget(standName(), target) then
                error("Skin/Stand changed before reset; stopped", 0)
            end
            say("No skin. Using Rokakaka...")
            local resetCharacter = player.Character
            local used, tool = useItem(FRUIT, false)
            itemDialogue(used, function() return standName() == nil end)
            say("Waiting for Rokakaka reset to finish...")
            waitItemSettled(tool, true, resetCharacter)
            waitReady(25)
            if standName() then error("Stand reset wasn't confirmed; stopped", 0) end
        end
        checkCancelled()
        waitReady(25)
        if not waitForTool(names) then return "No usable " .. itemLabel .. " found in the live inventory. Stopped." end
        say("Preparing " .. itemLabel .. " roll " .. (rolls + 1) .. "...")
        local used, tool = useItem(names, true)
        itemDialogue(used, function() return standName() ~= nil end)
        local grantedStand = standName()
        waitItemSettled(tool, false, nil, grantedStand)
        rolls += 1
        metrics.rolls = rolls
        say("Roll " .. rolls .. " completed. Waiting for Stand data...")
    end
    return "Stopped"
end




diagnostics.Provider = function()
    local snapshot = {
        config = {item = CONFIG.RollItem, target = CONFIG.TargetStand, maxRolls = CONFIG.MaxRolls},
        runtime = {alive = alive, busy = busy, looping = loopActive, cancelled = cancelled, inFlight = inFlight, rolls = metrics.rolls},
        activeItem = diagnostics.ActiveItem or "<none>",
        pendingInputHandler = diagnostics.Path(pendingInputHandler),
        character = diagnostics.Path(player.Character),
        inventory = {}, roots = {}, candidates = {}, choiceTextNodes = {},
    }
    local stats = player:FindFirstChild("PlayerStats")
    local busyOk, automationBusy = pcall(sourceBusy)
    if busyOk then snapshot.otherAutomationBusy = automationBusy else snapshot.otherAutomationError = tostring(automationBusy) end
    local value = stats and stats:FindFirstChild("Stand")
    snapshot.equippedStand = value and diagnostics.Property(value, "Value") or "<missing>"
    local serverState = _G.__StandLabSourceV10.GetServerState
    if serverState then local ok, state = pcall(serverState); if ok then snapshot.servers = state end end
    local skillTree = player:FindFirstChild("CharacterSkillTree")
    local worthiness = skillTree and skillTree:FindFirstChild("Worthiness")
    if worthiness then snapshot.worthiness = diagnostics.Property(worthiness, "Value") else snapshot.worthiness = "<missing>" end
    for _, container in ipairs(toolContainers(player.Character)) do
        local entry = {path = diagnostics.Path(container), class = container.ClassName, tools = {}}
        for _, item in ipairs(container:GetDescendants()) do
            if item:IsA("Tool") and #entry.tools < 48 then
                table.insert(entry.tools, {name = item.Name, normalized = normalizeName(item.Name), path = diagnostics.Path(item),
                    class = item.ClassName, enabled = diagnostics.Property(item, "Enabled"), toolTip = diagnostics.Property(item, "ToolTip")})
            end
        end
        table.insert(snapshot.inventory, entry)
    end
    local function visibilityDetails(object)
        local result = {visible = visible(object), ancestors = {}}
        local current = object
        while current and current ~= playerGui do
            if current:IsA("GuiObject") or current:IsA("ScreenGui") then
                local ancestor = {path = diagnostics.Path(current), class = current.ClassName}
                if current:IsA("GuiObject") then ancestor.visible = diagnostics.Property(current, "Visible") end
                if current:IsA("ScreenGui") then ancestor.enabled = diagnostics.Property(current, "Enabled") end
                table.insert(result.ancestors, ancestor)
            end
            if #result.ancestors >= 12 then break end
            current = current.Parent
        end
        return result
    end
    for _, root in ipairs(playerGui:GetChildren()) do
        if root ~= gui then table.insert(snapshot.roots, {name = root.Name, class = root.ClassName, path = diagnostics.Path(root)}) end
    end
    local expected = playerGui:FindFirstChild("DialogueGui")
    snapshot.expectedDialogue = expected and {path = diagnostics.Path(expected), class = expected.ClassName,
        visibility = visibilityDetails(expected)} or "<missing direct child named DialogueGui>"
    local captionsSeen, possible = {}, {}
    local function looksLikeChoice(text)
        local key = normalizeName((tostring(text):gsub("<[^>]*>", "")))
        return key == "yes" or key == "no" or key:match("^accept") or key:match("^reject")
            or key:find("continue", 1, true) or key == "skip"
    end
    for _, object in ipairs(playerGui:GetDescendants()) do
        if (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) and not object:IsDescendantOf(gui) then
            if looksLikeChoice(object.Text) and #snapshot.choiceTextNodes < 48 then
                table.insert(snapshot.choiceTextNodes, {path = diagnostics.Path(object), class = object.ClassName,
                    text = object.Text, visible = visible(object), parent = diagnostics.Path(object.Parent),
                    parentClass = object.Parent and object.Parent.ClassName or "<nil>"})
            end
        end
        if object:IsA("GuiButton") and not object:IsDescendantOf(gui) then
            local ok, caption = pcall(choiceCaption, object)
            local key = ok and normalizeName(caption) or ""
            local interesting = key == "yes" or key == "no" or key:match("^accept") or key:match("^reject")
                or key:find("continue", 1, true) or key == "skip"
            local childCaptions = {}
            for _, child in ipairs(object:GetDescendants()) do
                if child:IsA("TextLabel") then
                    if #childCaptions < 12 then table.insert(childCaptions, child.Text) end
                    if looksLikeChoice(child.Text) then interesting = true end
                end
            end
            if expected and object:IsDescendantOf(expected) then interesting = true end
            if interesting then
                local path = diagnostics.Path(object)
                if not captionsSeen[path] then
                    captionsSeen[path] = true
                    table.insert(possible, {object = object, path = path, caption = caption, key = key,
                        childCaptions = childCaptions, visible = visible(object)})
                end
            end
        end
    end
    table.sort(possible, function(a, b)
        if a.visible ~= b.visible then return a.visible end
        return a.path < b.path
    end)
    for index = 1, math.min(#possible, 32) do
        local candidate = possible[index]
        local object = candidate.object
        local nearby = {}
        local neighborhood = object.Parent and object.Parent.Parent
        if neighborhood then
            for _, text in ipairs(neighborhood:GetDescendants()) do
                if (text:IsA("TextLabel") or text:IsA("TextBox")) and visible(text) and #nearby < 12 then
                    table.insert(nearby, {path = diagnostics.Path(text), text = diagnostics.Property(text, "Text")})
                end
            end
        end
        table.insert(snapshot.candidates, {path = candidate.path, class = object.ClassName, caption = candidate.caption,
            childCaptions = candidate.childCaptions,
            rawText = diagnostics.Property(object, "Text"), normalized = candidate.key,
            visibility = visibilityDetails(object), interactable = diagnostics.Property(object, "Interactable"),
            active = diagnostics.Property(object, "Active"), signals = inputSignalDetails(object), nearbyTexts = nearby})
    end
    return snapshot
end
