            loopActive, SL_POLICY.RollActive = false, false
        end)
    end})
    controls:Button({Title = "Stop rolling", Icon = "square", Callback = function() diagnostics.Add("roll.stop-requested"); cancelled = true; say("Stopping. Already-sent requests may finish.") end})
    controls:Paragraph({Title = "Worthiness", Desc = "Uses only the single Worthiness node in your current game. Does not learn the rest of your skill tree."})
    skinLine = display:Paragraph({Title = "", Desc = "Skin: Unknown"})
    display:Button({Title = "Refresh skin", Icon = "refresh-cw", Callback = function()
        if loopActive or busy or inFlight > 0 or sourceBusy() then return end
        busy = true
        task.spawn(function()
            local ok, result = diagnostics.Try("skin.refresh", readSkin)
            if not ok then say(tostring(result)) end
            busy = false
        end)
    end})
    local viewerStatus = display:Paragraph({Title = "Stand preview", Desc = "Previewing does not summon or equip a Stand."})
    local viewer = display:Viewer({Name = "Stand model", Desc = "Loaded models only. Stored base models do not verify your equipped skin.", Players = false, Height = 280, Float = false, AutoRotate = true, SpinSpeed = 0.7})
    local function visiblePartCount(model)
        local count = 0
        for _, object in ipairs(model:GetDescendants()) do if object:IsA("BasePart") and object.Transparency < 1 then count += 1 end end
        return count
    end
local storedModelIndex
local function indexStoredModels()
    local storage = game:GetService("ReplicatedStorage")
    local index = {}
    for _, object in ipairs(storage:GetDescendants()) do
        if not alive then return {} end
        if object:IsA("Model") and object.Archivable and visiblePartCount(object) > 0 then
            -- Prefer an outer model, rather than an individual limb/accessory model.
            local ancestor, nested = object.Parent, false
            while ancestor and ancestor ~= storage do
                if ancestor:IsA("Model") then nested = true; break end
                ancestor = ancestor.Parent
            end
            if not nested then
                local keys = {[standKey(object.Name)] = 3}
                local parent = object.Parent
                if parent and parent ~= storage then keys[standKey(parent.Name)] = math.max(keys[standKey(parent.Name)] or 0, 2) end
                if parent and parent.Parent and parent.Parent ~= storage then
                    local key = standKey(parent.Parent.Name)
                    keys[key] = math.max(keys[key] or 0, 1)
                end
                table.insert(index, {source = object, keys = keys})
            end
        end
    end
    return index
end
local function findTargetTemplate(target)
    if not target or target == "" then return nil, "Choose a Stand first." end
    if not storedModelIndex then storedModelIndex = indexStoredModels() end
    local key, match, best, ambiguous = standKey(target), nil, 0, false
    for _, entry in ipairs(storedModelIndex) do
        local rank = entry.keys[key] or 0
        if entry.source.Parent and rank > 0 then
            if rank > best then match, best, ambiguous = entry.source, rank, false
            elseif rank == best and entry.source ~= match then ambiguous = true end
        end
    end
    if ambiguous then return nil, "Multiple stored models match " .. target .. "; the exact appearance is uncertain." end
    return match, "No stored model for " .. target .. ". This asset is not loaded on your client."
end

    local previewMode, lastModel, lastLabel = "current", nil, nil
    local function previewModel(model, label)
        if model == lastModel and label == lastLabel then return end
        if not viewer then viewerStatus:SetDesc("The source UI viewer is unavailable."); return end
        if not model then
            if viewer.Clear then viewer:Clear() end
            lastModel, lastLabel = nil, nil
            viewerStatus:SetDesc(label)
            return
        end
        local ok, problem = pcall(function()
            if viewer.Clear then viewer:Clear() end
            viewer:Add(model, label, true)
            if viewer.SetAutoRotate then viewer:SetAutoRotate(true) end
        end)
        if ok then lastModel, lastLabel = model, label; viewerStatus:SetDesc(label)
        else viewerStatus:SetDesc("Preview failed: " .. tostring(problem)) end
    end
    local function previewCurrent()
        local stats = player:FindFirstChild("PlayerStats")
        local value = stats and stats:FindFirstChild("Stand")
        local name = value and value.Value or "None"
        local serverModel, serverSkin = _G.__StandLabSourceV10.GetCurrentStandPreview()
        if serverModel then
            previewModel(serverModel, name .. (serverSkin == "" and " / no skin" or " / " .. serverSkin))
            return
        end
        local character = player.Character
        local morph = character and character:FindFirstChild("StandMorph")
        if morph and visiblePartCount(morph) > 0 then
            local skin = morph:FindFirstChild("StandSkin")
            local suffix = skin and skin:IsA("StringValue") and skin.Value ~= "" and (" / skin: " .. skin.Value) or " / loaded appearance"
            previewModel(morph, name .. suffix)
        elseif name ~= "None" and name ~= "" then
            local model, problem = findTargetTemplate(name)
            previewModel(model, model and (name .. " / stored base model; equipped skin unverified") or problem)
        else previewModel(nil, "No Stand equipped. Select a target to preview a loaded template.") end
    end
    display:Button({Title = "Preview current Stand", Desc = "Loads your current Stand from its data response without summoning.", Callback = function()
        if loopActive or busy or inFlight > 0 or sourceBusy() then return end
        previewMode, busy = "current", true
        task.spawn(function()
            local ok, result = pcall(readSkin)
            if ok then previewCurrent() else say(tostring(result)) end
            busy = false
        end)
    end})
    display:Button({Title = "Preview selected target", Desc = "Requires a matching model already stored on the client.", Callback = function()
        if CONFIG.TargetStand == "" then viewerStatus:SetDesc("Choose a target Stand first."); return end
        previewMode = "target"
        local model, problem = findTargetTemplate(CONFIG.TargetStand)
        previewModel(model, model and (CONFIG.TargetStand .. " / stored template") or problem)
    end})
    _G.__StandLabSourceV10.CancelRoll = function() cancelled = true end
    _G.__StandLabSourceV10.StopRoll = function() alive, cancelled = false, true end
    gui.Destroying:Connect(function() alive, cancelled, SL_POLICY.RollActive = false, true, false end)
    task.spawn(function()
        while alive do
            if previewMode == "current" then pcall(previewCurrent) end
            task.wait(1)
        end
    end)
end
